import { cn } from "@/lib/utils"

type Medium = "web" | "slide"
type Column = { heading?: string; body: string }
type SlideTwoColumnCopy = { heading: string; left: Column; right: Column }

function SlideColumn({ part, slide }: { part: Column; slide: boolean }) {
  return (
    <div className="flex flex-col gap-4 rounded-lg border border-border bg-card p-8 text-card-foreground">
      {part.heading ? <h3 className={cn("font-heading font-semibold", slide ? "text-4xl" : "text-xl")}>{part.heading}</h3> : null}
      <p className={cn("text-muted-foreground", slide ? "text-2xl" : "text-base")}>{part.body}</p>
    </div>
  )
}

export function SlideTwoColumn({ copy, medium = "web" }: { copy: SlideTwoColumnCopy; medium?: Medium }) {
  const slide = medium === "slide"
  return (
    <section data-slot="slide-two-column" data-medium={medium} className={cn("flex flex-col justify-center gap-8 bg-background text-foreground", slide ? "aspect-video w-full overflow-hidden px-24 py-20" : "px-6 py-20 md:px-12")}>
      <h2 className={cn("font-heading font-semibold tracking-tight", slide ? "text-6xl" : "text-3xl")}>{copy.heading}</h2>
      <div className={cn("grid gap-8", slide ? "grid-cols-2" : "md:grid-cols-2")}>
        <SlideColumn part={copy.left} slide={slide} />
        <SlideColumn part={copy.right} slide={slide} />
      </div>
    </section>
  )
}
